import numpy as np

def select_next_node(current_node, truck_nodes, depot_node, unvisited_nodes, distance_matrix):
    if len(unvisited_nodes) == 0:
        return depot_node
    distances = distance_matrix[current_node, unvisited_nodes]
    comp = np.array([np.sum(truck_nodes == n) for n in unvisited_nodes])
    scores = distances * (1 + comp)
    avg_dist = np.mean(distances)
    min_idx = np.argmin(scores)
    if scores[min_idx] <= avg_dist:
        return unvisited_nodes[min_idx]
    else:
        return next_node
